# shellcheck shell=sh
# softwary: `sync` command. Sourced by bin/softwary. POSIX sh.
#
# Builds every generated file in a work directory from the sources in
# .softwary/ (with .softwary/local/ overriding same-named sources), then
# compares the result with the repo. `sync` applies the difference,
# `sync --check` only reports it. Exit: 0 up to date, 1 out of date
# (--check), 2 configuration, source or conflict problem.

SW_TOOLS_REL=.softwary/config/tools.conf
SW_MANIFEST_REL=.softwary/generated
SW_BEGIN='<!-- softwary:begin: generated by ./softwary sync; do not edit -->'
SW_END='<!-- softwary:end -->'

sw_problem() {
	SW_PROBLEMS="${SW_PROBLEMS}$1
"
}

# sw_rel PATH: PATH relative to the repo root. The main checkout's package run
# on a job's worktree (the gate, the merge) reads the sources of its own
# .softwary/; they are the worktree's copy at the same place, so the generated
# files do not say where the main checkout is.
sw_rel() {
	case $1 in
	"$SOFTWARY_ROOT"/*) printf '%s' "${1#"$SOFTWARY_ROOT"/}" ;;
	"$SOFTWARY_HOME"/*) printf '.softwary/%s' "${1#"$SOFTWARY_HOME"/}" ;;
	*) printf '%s' "$1" ;;
	esac
}

# --- tools.conf -------------------------------------------------------------

# sw_targets: names of the available target scripts, one per line.
sw_targets() {
	for _f in "$SOFTWARY_HOME"/targets/*.sh "$SOFTWARY_HOME"/local/targets/*.sh; do
		[ -f "$_f" ] || continue
		_n=${_f##*/}
		printf '%s\n' "${_n%.sh}"
	done | sort -u
}

sw_target_path() {
	if [ -f "$SOFTWARY_HOME/local/targets/$1.sh" ]; then
		printf '%s' "$SOFTWARY_HOME/local/targets/$1.sh"
	else
		printf '%s' "$SOFTWARY_HOME/targets/$1.sh"
	fi
}

# sw_tools_load: reads tools.conf. Sets SW_TOOLS_ON (enabled tools) and adds
# every problem to SW_PROBLEMS.
sw_tools_load() {
	SW_TOOLS_ON=
	sw_kv_load "$SOFTWARY_ROOT/$SW_TOOLS_REL" "$SW_TOOLS_REL" SW_TOOLS tools
	if [ "$SW_TOOLS_FOUND" -eq 0 ]; then
		sw_problem "$SW_TOOLS_REL: file not found; rerun install.sh"
		return 0
	fi
	SW_PROBLEMS="$SW_PROBLEMS$SW_TOOLS_ERRORS"
	_known=$(sw_targets | tr '\n' ' ')
	for _t in $_known; do
		sw_valid_key tools "$_t" || sw_problem "targets/$_t.sh: invalid target name (use lowercase letters, digits, '-')"
	done
	for _k in $SW_TOOLS_KEYS; do
		_n=$(sw_kv_line SW_TOOLS "$_k")
		_v=$(sw_kv_get SW_TOOLS "$_k")
		if ! sw_in_list "$_k" "$_known"; then
			sw_problem "$SW_TOOLS_REL:$_n: unknown tool '$_k' (known: $(printf '%s' "$_known" | sed 's/ $//'))"
			continue
		fi
		case $_v in
		on) SW_TOOLS_ON="$SW_TOOLS_ON $_k" ;;
		off) ;;
		UNSET) sw_problem "$SW_TOOLS_REL:$_n: '$_k' is UNSET (set it to on or off)" ;;
		*) sw_problem "$SW_TOOLS_REL:$_n: invalid value '$_v' for '$_k' (use on or off)" ;;
		esac
	done
	for _t in $_known; do
		sw_in_list "$_t" "$SW_TOOLS_KEYS" || sw_problem "$SW_TOOLS_REL: '$_t' is missing (add '$_t = on' or '$_t = off')"
	done
}

# --- sources ----------------------------------------------------------------

# sw_source REL: path of a source, .softwary/local/ first.
sw_source() {
	if [ -e "$SOFTWARY_HOME/local/$1" ]; then
		printf '%s' "$SOFTWARY_HOME/local/$1"
	elif [ -e "$SOFTWARY_HOME/$1" ]; then
		printf '%s' "$SOFTWARY_HOME/$1"
	else
		return 1
	fi
}

# sw_source_names KIND: skill directory names or agent names, one per line.
sw_source_names() {
	for _base in "$SOFTWARY_HOME" "$SOFTWARY_HOME/local"; do
		if [ "$1" = skills ]; then
			for _d in "$_base"/skills/*/; do
				[ -d "$_d" ] || continue
				_d=${_d%/}
				printf '%s\n' "${_d##*/}"
			done
		else
			for _f in "$_base"/agents/*.md; do
				[ -f "$_f" ] || continue
				_f=${_f##*/}
				printf '%s\n' "${_f%.md}"
			done
		fi
	done | sort -u
}

# sw_valid_name NAME: lowercase letters, digits and inner '-'.
sw_valid_name() {
	case $1 in '' | [!a-z0-9]* | *[!a-z0-9-]* | *-) return 1 ;; esac
	return 0
}

# A carriage return: sources checked out with CRLF line endings (Git for
# Windows does so by default) are read as if they had LF.
SW_CR=$(printf '\r')

# sw_fm_check FILE NAME: validates a source's frontmatter: only single-line
# `name` (equal to NAME) and `description`. Sets _fm_end (closing line) and
# _fm_desc (the description line). Adds problems to SW_PROBLEMS.
sw_fm_check() {
	_rel=$(sw_rel "$1")
	_fm_end=0
	_fm_desc=
	_seen=
	_ln=0
	while IFS= read -r _l || [ -n "$_l" ]; do
		_l=${_l%"$SW_CR"}
		_ln=$((_ln + 1))
		if [ "$_ln" -eq 1 ]; then
			[ "$_l" = --- ] && continue
			sw_problem "$_rel:1: must start with a '---' frontmatter line"
			return 1
		fi
		if [ "$_l" = --- ]; then
			_fm_end=$_ln
			break
		fi
		case $_l in
		[a-z]*:\ *) ;;
		*)
			sw_problem "$_rel:$_ln: unsupported frontmatter line (use single-line 'key: value')"
			continue
			;;
		esac
		_k=${_l%%:*}
		_v=$(sw_trim "${_l#*:}")
		case $_k in
		name | description) ;;
		*)
			sw_problem "$_rel:$_ln: field '$_k' is not allowed (only name and description)"
			continue
			;;
		esac
		if sw_in_list "$_k" "$_seen"; then
			sw_problem "$_rel:$_ln: duplicate field '$_k'"
			continue
		fi
		_seen="$_seen $_k"
		if [ -z "$_v" ]; then
			sw_problem "$_rel:$_ln: '$_k' is empty"
		elif [ "$_k" = name ] && [ "$_v" != "$2" ]; then
			sw_problem "$_rel:$_ln: name '$_v' must be '$2'"
		fi
		[ "$_k" = description ] && _fm_desc=$_l
	done <"$1"
	if [ "$_fm_end" -eq 0 ]; then
		sw_problem "$_rel: frontmatter is not closed with '---'"
		return 1
	fi
	sw_in_list name "$_seen" || sw_problem "$_rel: missing 'name'"
	sw_in_list description "$_seen" || sw_problem "$_rel: missing 'description'"
	return 0
}

# sw_stage_doc SRC OUT NAME [MODEL]: writes SRC to OUT with normalised
# frontmatter (name: NAME, the source description, model: MODEL when given)
# and a do-not-edit note.
sw_stage_doc() {
	{
		printf -- '---\nname: %s\n%s\n' "$3" "$_fm_desc"
		[ -z "${4-}" ] || printf 'model: %s\n' "$4"
		printf -- '---\n'
		printf '<!-- Generated by ./softwary sync from %s. Do not edit. -->\n' "$(sw_rel "$1")"
		tail -n +"$((_fm_end + 1))" "$1" | tr -d '\r'
	} >"$2"
}

# sw_stage_sources DIR: resolves and validates the sources into DIR
# (rules/core.md, skills/softwary-<name>/, agents/<name>.md).
sw_stage_sources() {
	mkdir -p "$1/rules" "$1/skills" "$1/agents"
	if _core=$(sw_source rules/core.md); then
		tr -d '\r' <"$_core" >"$1/rules/core.md"
	else
		sw_problem ".softwary/rules/core.md: not found; rerun install.sh"
	fi
	for _n in $(sw_source_names skills); do
		_d=$(sw_source "skills/$_n")
		_rel=$(sw_rel "$_d")
		if ! sw_valid_name "$_n"; then
			sw_problem "$_rel: invalid skill name (use lowercase letters, digits, '-')"
			continue
		fi
		if [ ! -f "$_d/SKILL.md" ]; then
			sw_problem "$_rel/SKILL.md: not found"
			continue
		fi
		sw_fm_check "$_d/SKILL.md" "$_n" || continue
		cp -R "$_d" "$1/skills/softwary-$_n"
		sw_stage_doc "$_d/SKILL.md" "$1/skills/softwary-$_n/SKILL.md" "softwary-$_n"
	done
	# models.conf: a model per agent, only when the whole file is usable (doctor
	# reports it otherwise); targets that have no model field drop the line.
	_models_ok=0
	sw_models_load && _models_ok=1
	for _n in $(sw_source_names agents); do
		_f=$(sw_source "agents/$_n.md")
		if ! sw_valid_name "$_n"; then
			sw_problem "$(sw_rel "$_f"): invalid agent name (use lowercase letters, digits, '-')"
			continue
		fi
		sw_fm_check "$_f" "$_n" || continue
		if ! tail -n +"$((_fm_end + 1))" "$_f" | grep '[^[:space:]]' >/dev/null; then
			sw_problem "$(sw_rel "$_f"): the body (the agent's instructions) is empty"
			continue
		fi
		_model=
		[ "$_models_ok" -eq 0 ] || _model=$(sw_models_get "$_n")
		sw_stage_doc "$_f" "$1/agents/$_n.md" "$_n" "$_model"
	done
}

# --- building the generated output ------------------------------------------

# sw_merge FROM KIND OWNER: copies the KIND tree of a target into the stage,
# refusing paths that another target already produced.
sw_merge() {
	(cd "$1" && find . -type f) | sed 's#^\./##' | sort >"$SW_WORK/list"
	while IFS= read -r _p; do
		case $_p in
		*[[:space:]]*)
			sw_problem "target '$3' produced a path with whitespace: $_p"
			continue
			;;
		esac
		if [ -e "$SW_WORK/$2/$_p" ]; then
			sw_problem "$_p is produced by more than one target ($(cat "$SW_WORK/owner/$2/$_p") and $3)"
			continue
		fi
		mkdir -p "$(dirname "$SW_WORK/$2/$_p")" "$(dirname "$SW_WORK/owner/$2/$_p")"
		cp "$1/$_p" "$SW_WORK/$2/$_p"
		printf '%s' "$3" >"$SW_WORK/owner/$2/$_p"
	done <"$SW_WORK/list"
}

# sw_build: fills $SW_WORK/files (whole files) and $SW_WORK/blocks (block
# contents), keyed by repo-relative path.
sw_build() {
	_src=$SW_WORK/src
	mkdir -p "$SW_WORK/files" "$SW_WORK/blocks" "$SW_WORK/core/blocks" "$SW_WORK/owner"
	sw_stage_sources "$_src"
	[ -z "$SW_PROBLEMS" ] || return 0
	cp "$_src/rules/core.md" "$SW_WORK/core/blocks/AGENTS.md"
	sw_merge "$SW_WORK/core/blocks" blocks core
	for _t in $SW_TOOLS_ON; do
		_o=$SW_WORK/t/$_t
		mkdir -p "$_o/files" "$_o/blocks"
		if ! SOFTWARY_HOME=$SOFTWARY_HOME sh "$(sw_target_path "$_t")" "$_src" "$_o/files" "$_o/blocks" >"$_o.log" 2>&1; then
			sw_problem "target '$_t' failed: $(tail -n 3 "$_o.log" | tr '\n' ' ')"
			continue
		fi
		sw_merge "$_o/files" files "$_t"
		sw_merge "$_o/blocks" blocks "$_t"
	done
}

# --- comparing with the repo --------------------------------------------------

sw_cksum() {
	cksum <"$1" | awk '{ print $1 " " $2 }'
}

# sw_manifest_get KIND PATH: "cksum size" recorded for PATH, or nothing.
sw_manifest_get() {
	[ -f "$SOFTWARY_ROOT/$SW_MANIFEST_REL" ] || return 0
	awk -v k="$1" -v p="$2" '$1 == k && $4 == p { print $2 " " $3; exit }' "$SOFTWARY_ROOT/$SW_MANIFEST_REL"
}

# sw_block_extract FILE OUT: writes FILE's softwary block (markers included)
# to OUT. Returns 0 found, 1 absent, 2 malformed markers.
sw_block_extract() {
	[ -f "$1" ] || return 1
	_b=$(grep -c '^<!-- softwary:begin' "$1")
	_e=$(grep -c '^<!-- softwary:end -->$' "$1")
	[ "$_b" -eq 0 ] && [ "$_e" -eq 0 ] && return 1
	[ "$_b" -eq 1 ] && [ "$_e" -eq 1 ] || return 2
	awk '/^<!-- softwary:end -->$/ && !on { exit 3 }
		/^<!-- softwary:begin/ { on = 1 }
		on { print }
		on && /^<!-- softwary:end -->$/ { exit 0 }' "$1" >"$2" || return 2
}

# sw_plan_add STATUS KIND PATH
sw_plan_add() {
	printf '%s %s %s\n' "$1" "$2" "$3" >>"$SW_WORK/plan"
}

# sw_compare: classifies every generated path into $SW_WORK/plan as
# ok, missing, stale (source changed), modified (edited by hand), orphan or
# conflict, and writes the expected manifest to $SW_WORK/manifest.
sw_compare() {
	: >"$SW_WORK/plan"
	mkdir -p "$SW_WORK/want" "$SW_WORK/cur"
	{
		printf '# Generated by ./softwary sync: the files it owns. Do not edit.\n'
		(cd "$SW_WORK/files" && find . -type f) | sed 's#^\./##' | sort | while IFS= read -r _p; do
			printf 'file %s %s\n' "$(sw_cksum "$SW_WORK/files/$_p")" "$_p"
		done
		(cd "$SW_WORK/blocks" && find . -type f) | sed 's#^\./##' | sort | while IFS= read -r _p; do
			mkdir -p "$(dirname "$SW_WORK/want/$_p")"
			{
				printf '%s\n' "$SW_BEGIN"
				cat "$SW_WORK/blocks/$_p"
				[ -z "$(tail -c 1 "$SW_WORK/blocks/$_p")" ] || printf '\n'
				printf '%s\n' "$SW_END"
			} >"$SW_WORK/want/$_p"
			printf 'block %s %s\n' "$(sw_cksum "$SW_WORK/want/$_p")" "$_p"
		done
	} >"$SW_WORK/manifest"

	awk '$1 == "file" { print $4 }' "$SW_WORK/manifest" >"$SW_WORK/list"
	while IFS= read -r _p; do
		_d=$SOFTWARY_ROOT/$_p
		_m=$(sw_manifest_get file "$_p")
		if [ ! -e "$_d" ]; then
			sw_plan_add missing file "$_p"
		elif [ -z "$_m" ]; then
			sw_plan_add conflict file "$_p"
		elif cmp -s "$SW_WORK/files/$_p" "$_d"; then
			sw_plan_add ok file "$_p"
		elif [ "$(sw_cksum "$_d")" = "$_m" ]; then
			sw_plan_add stale file "$_p"
		else
			sw_plan_add modified file "$_p"
		fi
	done <"$SW_WORK/list"

	awk '$1 == "block" { print $4 }' "$SW_WORK/manifest" >"$SW_WORK/list"
	while IFS= read -r _p; do
		mkdir -p "$(dirname "$SW_WORK/cur/$_p")"
		_rc=0
		sw_block_extract "$SOFTWARY_ROOT/$_p" "$SW_WORK/cur/$_p" || _rc=$?
		if [ "$_rc" -eq 2 ]; then
			sw_plan_add malformed block "$_p"
		elif [ "$_rc" -eq 1 ]; then
			sw_plan_add missing block "$_p"
		elif cmp -s "$SW_WORK/want/$_p" "$SW_WORK/cur/$_p"; then
			sw_plan_add ok block "$_p"
		elif [ "$(sw_cksum "$SW_WORK/cur/$_p")" = "$(sw_manifest_get block "$_p")" ]; then
			sw_plan_add stale block "$_p"
		else
			sw_plan_add modified block "$_p"
		fi
	done <"$SW_WORK/list"

	[ -f "$SOFTWARY_ROOT/$SW_MANIFEST_REL" ] || return 0
	awk '$1 == "file" || $1 == "block" { print $1 " " $4 }' "$SOFTWARY_ROOT/$SW_MANIFEST_REL" >"$SW_WORK/list"
	while read -r _k _p; do
		awk -v k="$_k" -v p="$_p" '$1 == k && $4 == p { found = 1 } END { exit !found }' "$SW_WORK/manifest" && continue
		if [ "$_k" = file ]; then
			[ -e "$SOFTWARY_ROOT/$_p" ] && sw_plan_add orphan file "$_p"
		else
			_rc=0
			sw_block_extract "$SOFTWARY_ROOT/$_p" "$SW_WORK/list.block" || _rc=$?
			case $_rc in
			0) sw_plan_add orphan block "$_p" ;;
			2) sw_plan_add malformed block "$_p" ;;
			esac
		fi
	done <"$SW_WORK/list"
}

# sw_label KIND PATH: how a path is shown in reports.
sw_label() {
	if [ "$1" = block ]; then printf '%s (block)' "$2"; else printf '%s' "$2"; fi
}

# sw_report_blockers: prints conflicts and malformed blocks; true if any.
sw_report_blockers() {
	_any=1
	while read -r _s _k _p; do
		case $_s in
		conflict)
			printf 'conflict  %s (exists but was not generated by softwary; move it or rename the source)\n' "$_p"
			_any=0
			;;
		malformed)
			printf 'malformed %s (softwary block markers are broken; fix them by hand)\n' "$_p"
			_any=0
			;;
		esac
	done <"$SW_WORK/plan"
	return "$_any"
}

# --- applying -----------------------------------------------------------------

# sw_prune DIR: removes DIR and its empty parents, up to the repo root.
sw_prune() {
	_dir=$1
	while [ "$_dir" != . ] && [ "$_dir" != / ]; do
		rmdir "$SOFTWARY_ROOT/$_dir" 2>/dev/null || break
		_dir=$(dirname "$_dir")
	done
}

# sw_block_write FILE WANT: replaces FILE's block with WANT, or appends it.
sw_block_write() {
	if [ ! -s "$1" ]; then
		mkdir -p "$(dirname "$1")"
		cp "$2" "$1"
	elif sw_block_extract "$1" "$SW_WORK/tmp.block"; then
		awk -v want="$2" '
			/^<!-- softwary:begin/ { while ((getline l < want) > 0) print l; skip = 1; next }
			skip && /^<!-- softwary:end -->$/ { skip = 0; next }
			!skip { print }' "$1" >"$SW_WORK/tmp.file" && cp "$SW_WORK/tmp.file" "$1"
	else
		[ -z "$(tail -c 1 "$1")" ] || printf '\n' >>"$1"
		printf '\n' >>"$1"
		cat "$2" >>"$1"
	fi
}

# sw_block_remove FILE: removes FILE's block (and the blank line before it);
# deletes FILE when nothing else is left.
sw_block_remove() {
	awk '{ line[NR] = $0 }
		/^<!-- softwary:begin/ { b = NR }
		/^<!-- softwary:end -->$/ { e = NR }
		END {
			if (b > 1 && line[b - 1] == "") b--
			for (i = 1; i <= NR; i++) if (i < b || i > e) print line[i]
		}' "$1" >"$SW_WORK/tmp.file"
	if grep '[^[:space:]]' "$SW_WORK/tmp.file" >/dev/null; then
		cp "$SW_WORK/tmp.file" "$1"
	else
		rm "$1"
		sw_prune "$(dirname "$(sw_rel "$1")")"
	fi
}

sw_apply() {
	_changes=0
	while read -r _s _k _p; do
		[ "$_s" = ok ] && continue
		_d=$SOFTWARY_ROOT/$_p
		case $_s in
		missing) _msg="wrote    $(sw_label "$_k" "$_p")" ;;
		stale) _msg="updated  $(sw_label "$_k" "$_p")" ;;
		modified) _msg="updated  $(sw_label "$_k" "$_p") (overwrote edits by hand)" ;;
		orphan) _msg="removed  $(sw_label "$_k" "$_p")" ;;
		esac
		if [ "$_k" = file ]; then
			if [ "$_s" = orphan ]; then
				rm "$_d"
				sw_prune "$(dirname "$_p")"
			else
				mkdir -p "$(dirname "$_d")"
				cp "$SW_WORK/files/$_p" "$_d"
			fi
		elif [ "$_s" = orphan ]; then
			sw_block_remove "$_d"
		else
			sw_block_write "$_d" "$SW_WORK/want/$_p"
		fi
		printf '%s\n' "$_msg"
		_changes=$((_changes + 1))
	done <"$SW_WORK/plan"
	if ! cmp -s "$SW_WORK/manifest" "$SOFTWARY_ROOT/$SW_MANIFEST_REL"; then
		cp "$SW_WORK/manifest" "$SOFTWARY_ROOT/$SW_MANIFEST_REL"
		printf 'updated  %s\n' "$SW_MANIFEST_REL"
		_changes=$((_changes + 1))
	fi
	if [ "$_changes" -eq 0 ]; then
		printf 'sync: up to date\n'
	else
		printf 'sync: %s change(s)\n' "$_changes"
	fi
}

sw_check_report() {
	_out=0
	while read -r _s _k _p; do
		case $_s in
		missing) printf 'missing   %s\n' "$(sw_label "$_k" "$_p")" ;;
		stale) printf 'stale     %s\n' "$(sw_label "$_k" "$_p")" ;;
		modified) printf 'modified  %s (edited by hand)\n' "$(sw_label "$_k" "$_p")" ;;
		orphan) printf 'orphan    %s\n' "$(sw_label "$_k" "$_p")" ;;
		*) continue ;;
		esac
		_out=$((_out + 1))
	done <"$SW_WORK/plan"
	if [ ! -f "$SOFTWARY_ROOT/$SW_MANIFEST_REL" ]; then
		printf 'missing   %s\n' "$SW_MANIFEST_REL"
		_out=$((_out + 1))
	elif [ "$_out" -eq 0 ] && ! cmp -s "$SW_WORK/manifest" "$SOFTWARY_ROOT/$SW_MANIFEST_REL"; then
		printf 'stale     %s\n' "$SW_MANIFEST_REL"
		_out=$((_out + 1))
	fi
	if [ "$_out" -eq 0 ]; then
		printf 'sync --check: up to date\n'
		return 0
	fi
	printf 'sync --check: %s file(s) out of date; run ./softwary sync\n' "$_out"
	return 1
}

# sw_sync [--check]
sw_sync() {
	_check=0
	for _a in "$@"; do
		case $_a in
		--check) _check=1 ;;
		*)
			printf 'softwary sync: unknown option: %s\nusage: ./softwary sync [--check]\n' "$_a" >&2
			return 2
			;;
		esac
	done
	SW_PROBLEMS=
	sw_tools_load
	if [ -n "$SW_PROBLEMS" ]; then
		printf '%s' "$SW_PROBLEMS"
		printf 'sync: fix the problems above\n'
		return 2
	fi
	SW_WORK=$(mktemp -d "${TMPDIR:-/tmp}/softwary-sync.XXXXXX") || return 2
	trap 'rm -rf "$SW_WORK"' EXIT
	sw_build
	if [ -n "$SW_PROBLEMS" ]; then
		printf '%s' "$SW_PROBLEMS"
		printf 'sync: fix the problems above\n'
		return 2
	fi
	sw_compare
	if sw_report_blockers; then
		printf 'sync: nothing was written\n'
		return 2
	fi
	if [ "$_check" -eq 1 ]; then
		sw_check_report
		return $?
	fi
	sw_apply
}
